description:
Perhaps one of Hadley's earlier attempts. **pryr** is older than **purrr** I think. Not a real issue, just a comment. :)

```
> pryr::partial
function (`_f`, ..., .env = parent.frame(), .lazy = TRUE) 
{
    stopifnot(is.function(`_f`))
    if (.lazy) {
        fcall <- substitute(`_f`(...))
    }
    else {
        fcall <- make_call(substitute(`_f`), .args = list(...))
    }
    fcall[[length(fcall) + 1]] <- quote(...)
    args <- list(... = quote(expr = ))
    make_function(args, fcall, .env)
}
<environment: namespace:pryr>
> purrr::partial
function (...f, ..., .env = parent.frame(), .lazy = TRUE, .first = TRUE) 
{
    stopifnot(is.function(...f))
    if (.lazy) {
        fcall <- substitute(...f(...))
    }
    else {
        fcall <- make_call(substitute(...f), .args = list(...))
    }
    n <- length(fcall)
    if (!.first && n > 1) {
        tmp <- fcall[1]
        tmp[[2]] <- quote(...)
        tmp[seq(3, n + 1)] <- fcall[seq(2, n)]
        names(tmp)[seq(3, n + 1)] <- names2(fcall)[seq(2, n)]
        fcall <- tmp
    }
    else {
        fcall[[n + 1]] <- quote(...)
    }
    args <- list(... = quote(expr = ))
    make_function(args, fcall, .env)
}
<environment: namespace:purrr>
```


